    ? assignment.reads
    : effectiveRole === "source"
      ? allPages
      : effectiveRole === "assessment"
        ? question?.sourcePages || []
        : options.prepared && (effectiveRole === "teaching" || (effectiveRole === "visual" && isTextOnly))
          ? allPages
          : [];
